<?php require '../includes/auth.php';require_role('admin');$pdo=db();if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$status=post('status');$id=(int)post('id');if(in_array($status,['approved','rejected']))$pdo->prepare('UPDATE seller_profiles SET approval_status=?,approved_at=IF(?="approved",NOW(),NULL) WHERE id=?')->execute([$status,$status,$id]);flash('success','Seller registration updated.');redirect('admin/sellers.php');}$rows=$pdo->query('SELECT sp.*,u.name,u.email,u.phone FROM seller_profiles sp JOIN users u ON u.id=sp.user_id ORDER BY FIELD(approval_status,"pending","approved","rejected"),sp.id DESC')->fetchAll();$pageTitle='Manage sellers';require '../includes/header.php';?><div class="page-title"><p class="eyebrow">ADMIN</p><h1>Seller approvals</h1></div><div class="table-wrap"><table><thead><tr><th>Shop</th><th>Owner</th><th>Location</th><th>Status</th><th>Action</th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><b><?=e($r['shop_name'])?></b><br><small><?=e($r['description'])?></small></td><td><?=e($r['name'])?><br><small><?=e($r['email'])?></small></td><td><?=e($r['location'])?></td><td><span class="badge <?=status_class($r['approval_status'])?>"><?=e($r['approval_status'])?></span></td><td><form method="post"><input type="hidden" name="csrf" value="<?=csrf()?>"><input type="hidden" name="id" value="<?=$r['id']?>"><select name="status"><option value="approved">Approve</option><option value="rejected">Reject</option></select><button>Save</button></form></td></tr><?php endforeach;?></tbody></table></div><?php require '../includes/footer.php'; ?>
